public class Rechenwerk {

    public static int vervielfache(int zahl) {
        return zahl * 2;
    }

    public static double vervielfache(double zahl) {
        return zahl * 2;
    }

    public static void main(String[] args) {
        System.out.println("int: " + vervielfache(7));
        System.out.println("double: " + vervielfache(3.5));
    }
}

